using BmsDesktop.Infrastructure;
using Npgsql;
namespace BmsDesktop.Finance;
public sealed class PaymentService { private readonly Database _db; public PaymentService(Database db)=>_db=db; public async Task<Guid> CreateAsync(DateOnly date,string direction,decimal amount,string method,Guid? bank,string reference,string notes){if(amount<=0||!(direction is "IN" or "OUT"))throw new ArgumentException("Pembayaran tidak valid.");return await TransactionGuard.RunAsync(_db,async(cn,tx)=>{var id=Guid.NewGuid();await using var c=new NpgsqlCommand("insert into payments(id,payment_date,direction,amount,method,bank_account_id,reference_number,notes) values(@id,@d,@dir,@a,@m,@b,@r,@n)",cn,tx);c.Parameters.AddWithValue("id",id);c.Parameters.AddWithValue("d",date.ToDateTime(TimeOnly.MinValue));c.Parameters.AddWithValue("dir",direction);c.Parameters.AddWithValue("a",amount);c.Parameters.AddWithValue("m",method);c.Parameters.AddWithValue("b",(object?)bank??DBNull.Value);c.Parameters.AddWithValue("r",reference??"");c.Parameters.AddWithValue("n",notes??"");await c.ExecuteNonQueryAsync();return id;});} public async Task AllocateSalesAsync(Guid payment,Guid invoice,decimal amount)=>await Allocate(payment,invoice,null,amount); public async Task AllocateSupplierAsync(Guid payment,Guid invoice,decimal amount)=>await Allocate(payment,null,invoice,amount); private async Task Allocate(Guid payment,Guid? sales,Guid? supplier,decimal amount){if(amount<=0)throw new ArgumentException("Alokasi harus lebih dari nol.");await using var cn=await _db.OpenAsync();await using var c=new NpgsqlCommand("insert into payment_allocations(id,payment_id,sales_invoice_id,supplier_invoice_id,amount) values(@id,@p,@s,@sp,@a)",cn);c.Parameters.AddWithValue("id",Guid.NewGuid());c.Parameters.AddWithValue("p",payment);c.Parameters.AddWithValue("s",(object?)sales??DBNull.Value);c.Parameters.AddWithValue("sp",(object?)supplier??DBNull.Value);c.Parameters.AddWithValue("a",amount);await c.ExecuteNonQueryAsync();} }
